sutra:
rachana: 1
sutra: ctl-e2e
version: 1
description: Cashflows by leg.
match: { kind: ctl-trade }
title: { id: $.tradeId }
controls:
  - { id: b, kind: "top-n", options: [5, 10], default: 10 }
  - { id: c, kind: "date-range", default: "this-month" }
  - { id: a, kind: search }
panels:
  - id: cf
    kind: table
    title: Cashflows
    rows: $.cashflows
    columns:
      - { label: Leg, bind: "@.leg" }
      - { label: Amount, bind: "@.amount" }

